{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

type Config struct {
	Paths            []string
	Depth            int
	Threads          int
	ConfigFile       string
	NumberOfLines    int
	FullPaths        bool
	IgnoreDirs       []string
	IgnoreFile       string
	DereferenceLinks bool
	LimitFilesystem  bool
	ApparentSize     bool
	Reverse          bool
	NoColors         bool
	ForceColors      bool
	NoPercentBars    bool
	BarsOnRight      bool
	MinSizeStr       string
	MinSizeBytes     int64
	ScreenReader     bool
	SkipTotal        bool
	FileCount        bool
	IgnoreHidden     bool
	InvertFilterStr  []string
	FilterStr        []string
	FileTypes        bool
	TerminalWidth    int
	NoProgress       bool
	PrintErrors      bool
	OnlyDir          bool
	OnlyFile         bool
	OutputFormat     string
	StackSize        string
	OutputJSON       bool
	MTimeStr         string
	ATimeStr         string
	CTimeStr         string
	Files0From       string
	FilesFrom        string
	Collapse         []string
	FileTimeFormat   string

	// Internal
	hasExplicitN bool
}

type Node struct {
	Name      string
	Path      string
	RelPath   string
	IsDir     bool
	Size      int64
	MaxTime   time.Time
	Children  []*Node
	Parent    *Node
	Depth     int
	Dev       uint64
	Ino       uint64
	IsSymlink bool
	Ext       string
	IsLast    bool
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTermSize() (int, int) {
	ws := &winsize{}
	retCode, _, _ := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	col, row := int(ws.Col), int(ws.Row)
	if int(retCode) == -1 || col == 0 {
		col = 80
	}
	if int(retCode) == -1 || row == 0 {
		row = 20
	}
	return col, row
}

func isTTY(fd uintptr) bool {
	ws := &winsize{}
	retCode, _, _ := syscall.Syscall(syscall.SYS_IOCTL,
		fd,
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	return int(retCode) == 0 && ws.Col > 0
}

func main() {
	cfg := parseArgs()

	if cfg.NoProgress && !isTTY(os.Stderr.Fd()) {
		// ok
	} else if !cfg.NoProgress && isTTY(os.Stderr.Fd()) {
		defer fmt.Fprint(os.Stderr, "\r \r")
	}

	// Read input files from --files-from or --files0-from if present
	if cfg.FilesFrom != "" {
		paths := readPathsFromFile(cfg.FilesFrom, '\n')
		cfg.Paths = append(cfg.Paths, paths...)
	}
	if cfg.Files0From != "" {
		paths := readPathsFromFile(cfg.Files0From, 0)
		cfg.Paths = append(cfg.Paths, paths...)
	}

	if len(cfg.Paths) == 0 {
		cfg.Paths = []string{"."}
	}

	// Parse min size if given
	if cfg.MinSizeStr != "" {
		cfg.MinSizeBytes = parseMinSize(cfg.MinSizeStr)
	}

	// Parse filters
	filterRegexes := []*regexp.Regexp{}
	for _, f := range cfg.FilterStr {
		if re, err := regexp.Compile(f); err == nil {
			filterRegexes = append(filterRegexes, re)
		}
	}

	invertFilterRegexes := []*regexp.Regexp{}
	for _, f := range cfg.InvertFilterStr {
		if re, err := regexp.Compile(f); err == nil {
			invertFilterRegexes = append(invertFilterRegexes, re)
		}
	}

	if cfg.IgnoreFile != "" {
		lines := readLines(cfg.IgnoreFile)
		for _, l := range lines {
			l = strings.TrimSpace(l)
			if l != "" {
				if re, err := regexp.Compile(l); err == nil {
					invertFilterRegexes = append(invertFilterRegexes, re)
				}
			}
		}
	}

	// Process roots
	var rootNodes []*Node
	unreadableDirs := []string{}

	var rootDev uint64
	for i, path := range cfg.Paths {
		st, err := os.Lstat(path)
		if err != nil {
			if cfg.PrintErrors {
				fmt.Fprintf(os.Stderr, "dust: cannot access '%s': %v\n", path, err)
			}
			continue
		}
		if i == 0 {
			if sysSt, ok := st.Sys().(*syscall.Stat_t); ok {
				rootDev = uint64(sysSt.Dev)
			}
		}

		node := buildTree(path, path, 0, cfg, filterRegexes, invertFilterRegexes, rootDev, &unreadableDirs)
		if node != nil {
			rootNodes = append(rootNodes, node)
		}
	}

	if len(rootNodes) == 0 {
		return
	}

	var root *Node
	if len(rootNodes) == 1 {
		root = rootNodes[0]
	} else {
		// Multi-root total
		root = &Node{
			Name:     "(total)",
			Path:     "(total)",
			IsDir:    true,
			Children: rootNodes,
		}
		var totalSize int64
		var maxTime time.Time
		for _, r := range rootNodes {
			r.Parent = root
			totalSize += r.Size
			if r.MaxTime.After(maxTime) {
				maxTime = r.MaxTime
			}
		}
		root.Size = totalSize
		root.MaxTime = maxTime
	}

	// Handle --file-types (-t)
	if cfg.FileTypes {
		renderFileTypes(root, cfg)
		return
	}

	// Handle --output-json (-j)
	if cfg.OutputJSON {
		renderJSON(root, cfg)
		return
	}

	// Handle --only-file (-F) or --only-dir (-D)
	if cfg.OnlyFile {
		flattenFiles(root)
	} else if cfg.OnlyDir {
		filterOnlyDirs(root)
	}

	// Depth pruning & Number of lines selection
	pruneAndSelectNodes(root, cfg)

	// Render output
	renderTree(root, cfg)

	if len(unreadableDirs) > 0 && cfg.PrintErrors {
		fmt.Fprintf(os.Stderr, "\nDid not have permissions for directories: %s\n", strings.Join(unreadableDirs, ", "))
	}
}

func readLines(filePath string) []string {
	f, err := os.Open(filePath)
	if err != nil {
		return nil
	}
	defer f.Close()
	var lines []string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}
	return lines
}

func readPathsFromFile(filePath string, delim byte) []string {
	var r *os.File
	if filePath == "-" {
		r = os.Stdin
	} else {
		f, err := os.Open(filePath)
		if err != nil {
			return nil
		}
		defer f.Close()
		r = f
	}

	var paths []string
	sc := bufio.NewScanner(r)
	if delim == 0 {
		sc.Split(func(data []byte, atEOF bool) (advance int, token []byte, err error) {
			if atEOF && len(data) == 0 {
				return 0, nil, nil
			}
			if i := strings.IndexByte(string(data), 0); i >= 0 {
				return i + 1, data[0:i], nil
			}
			if atEOF {
				return len(data), data, nil
			}
			return 0, nil, nil
		})
	}
	for sc.Scan() {
		p := strings.TrimSpace(sc.Text())
		if p != "" {
			paths = append(paths, p)
		}
	}
	return paths
}

func parseMinSize(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	numStr := ""
	unitStr := ""
	for i, c := range s {
		if (c >= '0' && c <= '9') || c == '.' {
			numStr += string(c)
		} else {
			unitStr = strings.ToLower(strings.TrimSpace(s[i:]))
			break
		}
	}
	val, err := strconv.ParseFloat(numStr, 64)
	if err != nil {
		return 0
	}
	multiplier := float64(1)
	switch unitStr {
	case "k", "kb":
		multiplier = 1000
	case "ki", "kib":
		multiplier = 1024
	case "m", "mb":
		multiplier = 1000 * 1000
	case "mi", "mib":
		multiplier = 1024 * 1024
	case "g", "gb":
		multiplier = 1000 * 1000 * 1000
	case "gi", "gib":
		multiplier = 1024 * 1024 * 1024
	case "t", "tb":
		multiplier = 1000 * 1000 * 1000 * 1000
	case "ti", "tib":
		multiplier = 1024 * 1024 * 1024 * 1024
	case "b":
		multiplier = 1
	default:
		multiplier = 1024
	}
	return int64(val * multiplier)
}

func buildTree(path string, relPath string, depth int, cfg *Config, filters []*regexp.Regexp, invertFilters []*regexp.Regexp, rootDev uint64, unreadableDirs *[]string) *Node {
	st, err := os.Lstat(path)
	if err != nil {
		return nil
	}

	isSymlink := (st.Mode() & os.ModeSymlink) != 0
	isDir := st.IsDir()

	if isSymlink && cfg.DereferenceLinks {
		targetSt, err := os.Stat(path)
		if err == nil {
			st = targetSt
			isDir = st.IsDir()
		}
	}

	name := filepath.Base(path)
	if path == "." || path == ".." {
		name = path
	}

	// Hidden check
	if cfg.IgnoreHidden && strings.HasPrefix(name, ".") && name != "." && name != ".." {
		return nil
	}

	// Ignore dir check
	for _, ign := range cfg.IgnoreDirs {
		if path == ign || name == ign || relPath == ign {
			return nil
		}
	}

	// Regex filters
	if len(filters) > 0 {
		matched := false
		for _, re := range filters {
			if re.MatchString(path) {
				matched = true
				break
			}
		}
		if !matched && !isDir {
			return nil
		}
	}

	for _, re := range invertFilters {
		if re.MatchString(path) {
			return nil
		}
	}

	var dev, ino uint64
	if sysSt, ok := st.Sys().(*syscall.Stat_t); ok {
		dev = uint64(sysSt.Dev)
		ino = uint64(sysSt.Ino)
	}

	if cfg.LimitFilesystem && rootDev != 0 && dev != rootDev {
		return nil
	}

	// Time filters (-M, -A, -y)
	if !matchTimeFilters(st, cfg) {
		return nil
	}

	ext := ""
	if !isDir {
		ext = filepath.Ext(name)
	}

	node := &Node{
		Name:      name,
		Path:      path,
		RelPath:   relPath,
		IsDir:     isDir,
		Depth:     depth,
		Dev:       dev,
		Ino:       ino,
		IsSymlink: isSymlink,
		Ext:       ext,
	}

	modTime := st.ModTime()
	node.MaxTime = modTime

	// Check collapse
	isCollapsed := false
	for _, col := range cfg.Collapse {
		if name == col || path == col || relPath == col {
			isCollapsed = true
			break
		}
	}

	if isDir && !isCollapsed {
		entries, err := os.ReadDir(path)
		if err != nil {
			if unreadableDirs != nil {
				*unreadableDirs = append(*unreadableDirs, path)
			}
		} else {
			for _, entry := range entries {
				childPath := filepath.Join(path, entry.Name())
				childRel := filepath.Join(relPath, entry.Name())
				childNode := buildTree(childPath, childRel, depth+1, cfg, filters, invertFilters, rootDev, unreadableDirs)
				if childNode != nil {
					childNode.Parent = node
					node.Children = append(node.Children, childNode)
				}
			}
		}
	}

	// Compute size
	if cfg.FileCount {
		if !isDir && !isSymlink {
			node.Size = 1
		} else {
			var childCount int64
			for _, c := range node.Children {
				childCount += c.Size
			}
			node.Size = childCount
		}
	} else if cfg.FileTimeFormat != "" {
		// Filetime mode
		t := getStatTime(st, cfg.FileTimeFormat)
		node.MaxTime = t
		for _, c := range node.Children {
			if c.MaxTime.After(node.MaxTime) {
				node.MaxTime = c.MaxTime
			}
		}
		node.Size = node.MaxTime.Unix()
	} else {
		// Disk size vs Apparent size
		var selfSize int64
		if cfg.ApparentSize {
			selfSize = st.Size()
		} else {
			if sysSt, ok := st.Sys().(*syscall.Stat_t); ok {
				selfSize = sysSt.Blocks * 512
			} else {
				selfSize = st.Size()
			}
		}

		var childrenSize int64
		for _, c := range node.Children {
			childrenSize += c.Size
			if c.MaxTime.After(node.MaxTime) {
				node.MaxTime = c.MaxTime
			}
		}
		node.Size = selfSize + childrenSize
	}

	// Min size filter
	if cfg.MinSizeBytes > 0 && node.Size < cfg.MinSizeBytes {
		return nil
	}

	return node
}

func getStatTime(st os.FileInfo, timeType string) time.Time {
	if sysSt, ok := st.Sys().(*syscall.Stat_t); ok {
		switch timeType {
		case "a":
			return time.Unix(sysSt.Atim.Sec, sysSt.Atim.Nsec)
		case "c":
			return time.Unix(sysSt.Ctim.Sec, sysSt.Ctim.Nsec)
		default:
			return time.Unix(sysSt.Mtim.Sec, sysSt.Mtim.Nsec)
		}
	}
	return st.ModTime()
}

func matchTimeFilters(st os.FileInfo, cfg *Config) bool {
	checkSpec := func(spec string, t time.Time) bool {
		if spec == "" {
			return true
		}
		now := time.Now()
		diffDays := int(now.Sub(t).Hours() / 24)
		if strings.HasPrefix(spec, "+") {
			n, _ := strconv.Atoi(spec[1:])
			return diffDays > n
		} else if strings.HasPrefix(spec, "-") {
			n, _ := strconv.Atoi(spec[1:])
			return diffDays < n
		} else {
			n, _ := strconv.Atoi(spec)
			return diffDays == n
		}
	}

	if !checkSpec(cfg.MTimeStr, st.ModTime()) {
		return false
	}
	if sysSt, ok := st.Sys().(*syscall.Stat_t); ok {
		atime := time.Unix(sysSt.Atim.Sec, sysSt.Atim.Nsec)
		ctime := time.Unix(sysSt.Ctim.Sec, sysSt.Ctim.Nsec)
		if !checkSpec(cfg.ATimeStr, atime) {
			return false
		}
		if !checkSpec(cfg.CTimeStr, ctime) {
			return false
		}
	}
	return true
}

func flattenFiles(root *Node) {
	var files []*Node
	var collect func(n *Node)
	collect = func(n *Node) {
		if !n.IsDir {
			n.Parent = root
			files = append(files, n)
		}
		for _, c := range n.Children {
			collect(c)
		}
	}
	for _, c := range root.Children {
		collect(c)
	}
	root.Children = files
}

func filterOnlyDirs(root *Node) {
	var filter func(n *Node)
	filter = func(n *Node) {
		var newChildren []*Node
		for _, c := range n.Children {
			if c.IsDir || c.IsSymlink {
				filter(c)
				newChildren = append(newChildren, c)
			}
		}
		n.Children = newChildren
	}
	filter(root)
}

func pruneAndSelectNodes(root *Node, cfg *Config) {
	// Sort children recursively
	var sortChildren func(n *Node)
	sortChildren = func(n *Node) {
		sort.Slice(n.Children, func(i, j int) bool {
			if n.Children[i].Size == n.Children[j].Size {
				return n.Children[i].Name < n.Children[j].Name
			}
			return n.Children[i].Size > n.Children[j].Size
		})
		for _, c := range n.Children {
			sortChildren(c)
		}
	}
	sortChildren(root)

	// Filter depth
	if cfg.Depth > 0 {
		var limitDepth func(n *Node)
		limitDepth = func(n *Node) {
			if n.Depth >= cfg.Depth {
				n.Children = nil
				return
			}
			for _, c := range n.Children {
				limitDepth(c)
			}
		}
		limitDepth(root)
	}

	// Select top N nodes by size
	maxLines := cfg.NumberOfLines
	if maxLines <= 0 {
		maxLines = 20
	}

	var allNodes []*Node
	var collectAll func(n *Node)
	collectAll = func(n *Node) {
		if n != root {
			allNodes = append(allNodes, n)
		}
		for _, c := range n.Children {
			collectAll(c)
		}
	}
	collectAll(root)

	sort.Slice(allNodes, func(i, j int) bool {
		if allNodes[i].Size == allNodes[j].Size {
			return allNodes[i].Depth < allNodes[j].Depth
		}
		return allNodes[i].Size > allNodes[j].Size
	})

	selected := make(map[*Node]bool)
	selected[root] = true

	count := 0
	for _, n := range allNodes {
		if count >= maxLines {
			break
		}
		selected[n] = true
		curr := n.Parent
		for curr != nil {
			selected[curr] = true
			curr = curr.Parent
		}
		count++
	}

	var prune func(n *Node)
	prune = func(n *Node) {
		var activeChildren []*Node
		for _, c := range n.Children {
			if selected[c] {
				prune(c)
				activeChildren = append(activeChildren, c)
			}
		}
		n.Children = activeChildren
	}
	prune(root)
}

func formatSize(size int64, cfg *Config) string {
	if cfg.FileCount {
		return strconv.FormatInt(size, 10)
	}
	if cfg.FileTimeFormat != "" {
		t := time.Unix(size, 0).Local()
		return t.Format("2006-01-02T15:04:05")
	}

	fmtMode := cfg.OutputFormat
	switch fmtMode {
	case "b":
		return fmt.Sprintf("%dB", size)
	case "k":
		return fmt.Sprintf("%dK", size/1024)
	case "m":
		return fmt.Sprintf("%dM", size/(1024*1024))
	case "g":
		return fmt.Sprintf("%dG", size/(1024*1024*1024))
	case "t":
		return fmt.Sprintf("%dT", size/(1024*1024*1024*1024))
	case "kb":
		return fmt.Sprintf("%dK", size/1000)
	case "mb":
		return fmt.Sprintf("%dM", size/(1000*1000))
	case "gb":
		return fmt.Sprintf("%dG", size/(1000*1000*1000))
	case "tb":
		return fmt.Sprintf("%dT", size/(1000*1000*1000*1000))
	case "si":
		return formatBytesUnit(size, 1000)
	default:
		return formatBytesUnit(size, 1024)
	}
}

func formatBytesUnit(size int64, base float64) string {
	if size < int64(base) {
		return fmt.Sprintf("%dB", size)
	}
	units := []string{"K", "M", "G", "T", "P", "E"}
	val := float64(size)
	unitIdx := -1
	for val >= base && unitIdx < len(units)-1 {
		val /= base
		unitIdx++
	}
	if val < 10.0 {
		return fmt.Sprintf("%.1f%s", val, units[unitIdx])
	}
	return fmt.Sprintf("%.0f%s", val, units[unitIdx])
}

type DrawItem struct {
	Node        *Node
	TreePrefix  string
	DisplayName string
	SizeStr     string
	PctVal      float64
}

func renderTree(root *Node, cfg *Config) {
	// Build flat list of items to draw
	var items []*DrawItem

	// Mark last children for color assignment
	markLastChildren(root)

	if cfg.Reverse {
		buildDrawItemsTopDown(root, "", true, cfg, &items)
	} else {
		buildDrawItemsBottomUp(root, "", true, cfg, &items)
	}

	if cfg.SkipTotal {
		// Omit root item from display
		var filtered []*DrawItem
		for _, item := range items {
			if item.Node != root {
				filtered = append(filtered, item)
			}
		}
		items = filtered
	}

	if len(items) == 0 {
		return
	}

	if cfg.ScreenReader {
		renderScreenReader(items, cfg)
		return
	}

	maxSizeLen := 0
	maxTreeNameLen := 0
	for _, it := range items {
		if len(it.SizeStr) > maxSizeLen {
			maxSizeLen = len(it.SizeStr)
		}
		tnLen := len(it.TreePrefix) + len(it.DisplayName)
		if tnLen > maxTreeNameLen {
			maxTreeNameLen = tnLen
		}
	}

	termWidth := cfg.TerminalWidth
	if termWidth <= 0 {
		w, _ := getTermSize()
		termWidth = w
	}

	// Line components:
	// Size (maxSizeLen) + " " + TreeName (maxTreeNameLen) + " " + "│" + Bar + "│" + " " + Pct (5)
	// Fixed overhead = maxSizeLen + 1 + maxTreeNameLen + 1 + 1 + 5 = maxSizeLen + maxTreeNameLen + 8
	fixedWidth := maxSizeLen + maxTreeNameLen + 8
	barWidth := termWidth - fixedWidth

	useBars := !cfg.NoPercentBars && barWidth >= 3 && cfg.FileTimeFormat == ""

	// Colors enabled check
	useColors := false
	if cfg.ForceColors {
		useColors = true
	} else if !cfg.NoColors && isTTY(os.Stdout.Fd()) {
		useColors = true
	}

	for _, item := range items {
		// Size string
		sizePadded := fmt.Sprintf("%*s", maxSizeLen, item.SizeStr)
		if useColors && item.Node.IsLast {
			sizePadded = "\x1b[31m" + sizePadded + "\x1b[0m"
		}

		// Display name
		displayNameStr := item.DisplayName
		if useColors && item.Node.IsDir {
			displayNameStr = "\x1b[1;34m" + displayNameStr + "\x1b[0m"
		}

		treeAndName := fmt.Sprintf("%-*s", maxTreeNameLen, item.TreePrefix+item.DisplayName)
		if useColors && item.Node.IsDir {
			// adjust for ansi codes in length calculation
			padLen := maxTreeNameLen - (len(item.TreePrefix) + len(item.DisplayName))
			treeAndName = item.TreePrefix + "\x1b[1;34m" + item.DisplayName + "\x1b[0m" + strings.Repeat(" ", padLen)
		}

		if !useBars {
			if cfg.NoPercentBars || cfg.FileTimeFormat != "" {
				fmt.Printf("%s   %s\n", sizePadded, item.TreePrefix+displayNameStr)
			} else {
				fmt.Printf("%s   %s\n", sizePadded, treeAndName)
			}
			continue
		}

		// Draw bar
		barStr := drawBar(item.Node, root, barWidth, cfg.BarsOnRight)
		pctStr := fmt.Sprintf("%3.0f%%", item.PctVal)

		if cfg.BarsOnRight {
			fmt.Printf("%s   %s │ %s │ %s\n", sizePadded, treeAndName, barStr, pctStr)
		} else {
			fmt.Printf("%s   %s │%s│ %s\n", sizePadded, treeAndName, barStr, pctStr)
		}
	}
}

func markLastChildren(n *Node) {
	n.IsLast = true // root is last
	var mark func(curr *Node)
	mark = func(curr *Node) {
		for i, c := range curr.Children {
			if i == len(curr.Children)-1 {
				c.IsLast = true
			} else {
				c.IsLast = false
			}
			mark(c)
		}
	}
	mark(n)
}

func buildDrawItemsBottomUp(n *Node, prefix string, isTop bool, cfg *Config, items *[]*DrawItem) {
	// First process children in reverse order (bottom-up: smaller/first siblings higher, parent at bottom)
	for i := len(n.Children) - 1; i >= 0; i-- {
		child := n.Children[i]

		var childPrefix string
		if isTop {
			childPrefix = ""
		} else {
			// ancestor vertical lines
			if i == len(n.Children)-1 {
				childPrefix = prefix + "  "
			} else {
				childPrefix = prefix + "│ "
			}
		}

		buildDrawItemsBottomUp(child, childPrefix, false, cfg, items)
	}

	// Now process self
	var treeSymbol string
	if n.Parent == nil {
		if len(n.Children) > 0 {
			treeSymbol = "┌─┴ "
		} else {
			treeSymbol = "┌── "
		}
	} else {
		isFirstChild := (n == n.Parent.Children[0])
		hasChildren := len(n.Children) > 0

		if isFirstChild && hasChildren {
			treeSymbol = "┌─┴ "
		} else if isFirstChild && !hasChildren {
			treeSymbol = "┌── "
		} else if !isFirstChild && hasChildren {
			treeSymbol = "├─┴ "
		} else { // !isFirstChild && !hasChildren
			treeSymbol = "├── "
		}
	}

	displayName := n.Name
	if cfg.FullPaths {
		displayName = n.Path
	} else if n.Parent == nil {
		displayName = n.Path
	}

	pct := 0.0
	if n.Parent == nil {
		pct = 100.0
	} else if n.Parent.Size > 0 {
		pct = float64(n.Size) / float64(findRootSize(n)) * 100.0
	}

	*items = append(*items, &DrawItem{
		Node:        n,
		TreePrefix:  prefix + treeSymbol,
		DisplayName: displayName,
		SizeStr:     formatSize(n.Size, cfg),
		PctVal:      pct,
	})
}

func buildDrawItemsTopDown(n *Node, prefix string, isTop bool, cfg *Config, items *[]*DrawItem) {
	// Self first
	var treeSymbol string
	if n.Parent == nil {
		if len(n.Children) > 0 {
			treeSymbol = "└─┬ "
		} else {
			treeSymbol = "└── "
		}
	} else {
		isLastChild := (n == n.Parent.Children[len(n.Parent.Children)-1])
		hasChildren := len(n.Children) > 0

		if isLastChild && hasChildren {
			treeSymbol = "└─┬ "
		} else if isLastChild && !hasChildren {
			treeSymbol = "└── "
		} else if !isLastChild && hasChildren {
			treeSymbol = "├─┬ "
		} else {
			treeSymbol = "├── "
		}
	}

	displayName := n.Name
	if cfg.FullPaths {
		displayName = n.Path
	} else if n.Parent == nil {
		displayName = n.Path
	}

	pct := 0.0
	rootSize := findRootSize(n)
	if rootSize > 0 {
		pct = float64(n.Size) / float64(rootSize) * 100.0
	}

	*items = append(*items, &DrawItem{
		Node:        n,
		TreePrefix:  prefix + treeSymbol,
		DisplayName: displayName,
		SizeStr:     formatSize(n.Size, cfg),
		PctVal:      pct,
	})

	// Process children top-down
	for i, child := range n.Children {
		var childPrefix string
		if isTop {
			childPrefix = "  "
		} else {
			if i == len(n.Children)-1 {
				childPrefix = prefix + "  "
			} else {
				childPrefix = prefix + "│ "
			}
		}

		buildDrawItemsTopDown(child, childPrefix, false, cfg, items)
	}
}

func findRootSize(n *Node) int64 {
	curr := n
	for curr.Parent != nil {
		curr = curr.Parent
	}
	return curr.Size
}

func drawBar(node *Node, root *Node, width int, alignRight bool) string {
	if width <= 0 {
		return ""
	}

	rootSize := float64(root.Size)
	if rootSize <= 0 {
		return strings.Repeat(" ", width)
	}

	// Measure sizes at levels:
	// Self, Parent, Grandparent, Great-grandparent...
	selfSize := float64(node.Size)

	selfLen := int(selfSize / rootSize * float64(width))
	if selfSize > 0 && selfLen == 0 {
		selfLen = 1
	}

	var parentLen, gParentLen, ggParentLen int

	if node.Parent != nil {
		pSize := float64(node.Parent.Size)
		pTotal := int(pSize / rootSize * float64(width))
		if pTotal > selfLen {
			parentLen = pTotal - selfLen
		}

		if node.Parent.Parent != nil {
			gpSize := float64(node.Parent.Parent.Size)
			gpTotal := int(gpSize / rootSize * float64(width))
			if gpTotal > selfLen+parentLen {
				gParentLen = gpTotal - (selfLen + parentLen)
			}

			if node.Parent.Parent.Parent != nil {
				ggpSize := float64(node.Parent.Parent.Parent.Size)
				ggpTotal := int(ggpSize / rootSize * float64(width))
				if ggpTotal > selfLen+parentLen+gParentLen {
					ggParentLen = ggpTotal - (selfLen + parentLen + gParentLen)
				}
			}
		}
	}

	totalFilled := selfLen + parentLen + gParentLen + ggParentLen
	if totalFilled > width {
		// adjust
		excess := totalFilled - width
		if ggParentLen >= excess {
			ggParentLen -= excess
		} else if gParentLen >= excess {
			gParentLen -= excess
		} else if parentLen >= excess {
			parentLen -= excess
		}
	}

	emptyLen := width - (selfLen + parentLen + gParentLen + ggParentLen)
	if emptyLen < 0 {
		emptyLen = 0
	}

	// Chars: █ (self), ▓ (parent), ▒ (gparent), ░ (ggparent), space
	bar := strings.Repeat("█", selfLen) +
		strings.Repeat("▓", parentLen) +
		strings.Repeat("▒", gParentLen) +
		strings.Repeat("░", ggParentLen) +
		strings.Repeat(" ", emptyLen)

	if alignRight {
		// Reverse string for right alignment
		bar = strings.Repeat(" ", emptyLen) +
			strings.Repeat("░", ggParentLen) +
			strings.Repeat("▒", gParentLen) +
			strings.Repeat("▓", parentLen) +
			strings.Repeat("█", selfLen)
	}

	return bar
}

func renderScreenReader(items []*DrawItem, cfg *Config) {
	maxNameLen := 0
	maxSizeLen := 0

	for _, it := range items {
		if len(it.DisplayName) > maxNameLen {
			maxNameLen = len(it.DisplayName)
		}
		if len(it.SizeStr) > maxSizeLen {
			maxSizeLen = len(it.SizeStr)
		}
	}

	for _, it := range items {
		pctStr := fmt.Sprintf("%3.0f%%", it.PctVal)
		fmt.Printf("%-*s %d %*s %s\n", maxNameLen, it.DisplayName, it.Node.Depth, maxSizeLen, it.SizeStr, pctStr)
	}
}

func renderJSON(root *Node, cfg *Config) {
	type JSONNode struct {
		Size     string      `json:"size"`
		Name     string      `json:"name"`
		Children []*JSONNode `json:"children"`
	}

	var convert func(n *Node) *JSONNode
	convert = func(n *Node) *JSONNode {
		displayName := n.Path
		if n.Name == "(total)" {
			displayName = "(total)"
		}
		jn := &JSONNode{
			Size:     formatSize(n.Size, cfg),
			Name:     displayName,
			Children: []*JSONNode{},
		}
		for _, c := range n.Children {
			jn.Children = append(jn.Children, convert(c))
		}
		return jn
	}

	res := convert(root)
	enc, _ := json.Marshal(res)
	fmt.Println(string(enc))
}

func renderFileTypes(root *Node, cfg *Config) {
	extSizes := make(map[string]int64)
	var collect func(n *Node)
	collect = func(n *Node) {
		if !n.IsDir {
			ext := n.Ext
			if ext == "" {
				ext = "(no extension)"
			}
			extSizes[ext] += n.Size
		}
		for _, c := range n.Children {
			collect(c)
		}
	}
	collect(root)

	type TypeItem struct {
		Ext  string
		Size int64
	}
	var list []TypeItem
	var totalSize int64
	for ext, sz := range extSizes {
		list = append(list, TypeItem{Ext: ext, Size: sz})
		totalSize += sz
	}

	sort.Slice(list, func(i, j int) bool {
		return list[i].Size > list[j].Size
	})

	type NodeItem struct {
		Name string
		Size int64
	}
	var items []NodeItem
	for _, it := range list {
		items = append(items, NodeItem{Name: it.Ext, Size: it.Size})
	}
	items = append(items, NodeItem{Name: "(total)", Size: totalSize})

	maxSizeLen := 0
	maxNameLen := 0
	for _, it := range items {
		sStr := formatSize(it.Size, cfg)
		if len(sStr) > maxSizeLen {
			maxSizeLen = len(sStr)
		}
		if len(it.Name) > maxNameLen {
			maxNameLen = len(it.Name)
		}
	}

	termWidth := cfg.TerminalWidth
	if termWidth <= 0 {
		w, _ := getTermSize()
		termWidth = w
	}

	for i, it := range items {
		isRoot := (i == len(items)-1)
		sStr := formatSize(it.Size, cfg)
		sPadded := fmt.Sprintf("%*s", maxSizeLen, sStr)

		var treePrefix string
		if isRoot {
			treePrefix = "┌─┴ "
		} else if i == 0 {
			treePrefix = "┌── "
		} else {
			treePrefix = "├── "
		}

		tnPadded := fmt.Sprintf("%-*s", maxNameLen+len(treePrefix), treePrefix+it.Name)
		pct := float64(it.Size) / float64(totalSize) * 100.0
		if totalSize == 0 {
			pct = 0
		}

		fixedWidth := maxSizeLen + maxNameLen + len(treePrefix) + 8
		barWidth := termWidth - fixedWidth
		if barWidth < 3 {
			fmt.Printf("%s   %s\n", sPadded, treePrefix+it.Name)
			continue
		}

		selfLen := int(pct / 100.0 * float64(barWidth))
		if it.Size > 0 && selfLen == 0 {
			selfLen = 1
		}
		emptyLen := barWidth - selfLen
		if emptyLen < 0 {
			emptyLen = 0
		}

		barStr := strings.Repeat("█", selfLen) + strings.Repeat(" ", emptyLen)
		pctStr := fmt.Sprintf("%3.0f%%", pct)

		fmt.Printf("%s   %s │%s│ %s\n", sPadded, tnPadded, barStr, pctStr)
	}
}

func parseArgs() *Config {
	cfg := &Config{
		Depth:         0,
		NumberOfLines: 0,
		OutputFormat:  "default",
	}

	// First pass to find --config file
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		if args[i] == "--config" && i+1 < len(args) {
			cfg.ConfigFile = args[i+1]
		} else if strings.HasPrefix(args[i], "--config=") {
			cfg.ConfigFile = strings.TrimPrefix(args[i], "--config=")
		}
	}

	// Load config file if present
	if cfg.ConfigFile != "" {
		loadConfigFile(cfg, cfg.ConfigFile)
	} else {
		home, _ := os.UserHomeDir()
		if home != "" {
			c1 := filepath.Join(home, ".config", "dust", "config.toml")
			if _, err := os.Stat(c1); err == nil {
				loadConfigFile(cfg, c1)
			} else {
				c2 := filepath.Join(home, ".dust.toml")
				if _, err := os.Stat(c2); err == nil {
					loadConfigFile(cfg, c2)
				}
			}
		}
	}

	// Parse command line args
	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "-h" {
			printShortHelp()
			os.Exit(0)
		} else if arg == "--help" {
			printLongHelp()
			os.Exit(0)
		} else if arg == "-V" || arg == "--version" {
			fmt.Println("Dust 1.2.3")
			os.Exit(0)
		} else if arg == "-d" || arg == "--depth" {
			i++
			if i < len(args) {
				cfg.Depth, _ = strconv.Atoi(args[i])
			}
		} else if strings.HasPrefix(arg, "--depth=") {
			cfg.Depth, _ = strconv.Atoi(strings.TrimPrefix(arg, "--depth="))
		} else if arg == "-n" || arg == "--number-of-lines" {
			i++
			if i < len(args) {
				cfg.NumberOfLines, _ = strconv.Atoi(args[i])
				cfg.hasExplicitN = true
			}
		} else if strings.HasPrefix(arg, "--number-of-lines=") {
			cfg.NumberOfLines, _ = strconv.Atoi(strings.TrimPrefix(arg, "--number-of-lines="))
			cfg.hasExplicitN = true
		} else if arg == "-p" || arg == "--full-paths" {
			cfg.FullPaths = true
		} else if arg == "-X" || arg == "--ignore-directory" {
			i++
			if i < len(args) {
				cfg.IgnoreDirs = append(cfg.IgnoreDirs, args[i])
			}
		} else if strings.HasPrefix(arg, "--ignore-directory=") {
			cfg.IgnoreDirs = append(cfg.IgnoreDirs, strings.TrimPrefix(arg, "--ignore-directory="))
		} else if arg == "-I" || arg == "--ignore-all-in-file" {
			i++
			if i < len(args) {
				cfg.IgnoreFile = args[i]
			}
		} else if strings.HasPrefix(arg, "--ignore-all-in-file=") {
			cfg.IgnoreFile = strings.TrimPrefix(arg, "--ignore-all-in-file=")
		} else if arg == "-L" || arg == "--dereference-links" {
			cfg.DereferenceLinks = true
		} else if arg == "-x" || arg == "--limit-filesystem" {
			cfg.LimitFilesystem = true
		} else if arg == "-s" || arg == "--apparent-size" {
			cfg.ApparentSize = true
		} else if arg == "-r" || arg == "--reverse" {
			cfg.Reverse = true
		} else if arg == "-c" || arg == "--no-colors" {
			cfg.NoColors = true
		} else if arg == "-C" || arg == "--force-colors" {
			cfg.ForceColors = true
		} else if arg == "-b" || arg == "--no-percent-bars" {
			cfg.NoPercentBars = true
		} else if arg == "-B" || arg == "--bars-on-right" {
			cfg.BarsOnRight = true
		} else if arg == "-z" || arg == "--min-size" {
			i++
			if i < len(args) {
				cfg.MinSizeStr = args[i]
			}
		} else if strings.HasPrefix(arg, "--min-size=") {
			cfg.MinSizeStr = strings.TrimPrefix(arg, "--min-size=")
		} else if arg == "-R" || arg == "--screen-reader" {
			cfg.ScreenReader = true
		} else if arg == "--skip-total" {
			cfg.SkipTotal = true
		} else if arg == "-f" || arg == "--filecount" {
			cfg.FileCount = true
		} else if arg == "-i" || arg == "--ignore-hidden" {
			cfg.IgnoreHidden = true
		} else if arg == "-v" || arg == "--invert-filter" {
			i++
			if i < len(args) {
				cfg.InvertFilterStr = append(cfg.InvertFilterStr, args[i])
			}
		} else if strings.HasPrefix(arg, "--invert-filter=") {
			cfg.InvertFilterStr = append(cfg.InvertFilterStr, strings.TrimPrefix(arg, "--invert-filter="))
		} else if arg == "-e" || arg == "--filter" {
			i++
			if i < len(args) {
				cfg.FilterStr = append(cfg.FilterStr, args[i])
			}
		} else if strings.HasPrefix(arg, "--filter=") {
			cfg.FilterStr = append(cfg.FilterStr, strings.TrimPrefix(arg, "--filter="))
		} else if arg == "-t" || arg == "--file-types" {
			cfg.FileTypes = true
		} else if arg == "-w" || arg == "--terminal-width" {
			i++
			if i < len(args) {
				cfg.TerminalWidth, _ = strconv.Atoi(args[i])
			}
		} else if strings.HasPrefix(arg, "--terminal-width=") {
			cfg.TerminalWidth, _ = strconv.Atoi(strings.TrimPrefix(arg, "--terminal-width="))
		} else if arg == "-P" || arg == "--no-progress" {
			cfg.NoProgress = true
		} else if arg == "--print-errors" {
			cfg.PrintErrors = true
		} else if arg == "-D" || arg == "--only-dir" {
			cfg.OnlyDir = true
		} else if arg == "-F" || arg == "--only-file" {
			cfg.OnlyFile = true
		} else if arg == "-o" || arg == "--output-format" {
			i++
			if i < len(args) {
				cfg.OutputFormat = args[i]
			}
		} else if strings.HasPrefix(arg, "--output-format=") {
			cfg.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
		} else if arg == "-S" || arg == "--stack-size" {
			i++
			if i < len(args) {
				cfg.StackSize = args[i]
			}
		} else if arg == "-j" || arg == "--output-json" {
			cfg.OutputJSON = true
		} else if arg == "-M" || arg == "--mtime" {
			i++
			if i < len(args) {
				cfg.MTimeStr = args[i]
			}
		} else if arg == "-A" || arg == "--atime" {
			i++
			if i < len(args) {
				cfg.ATimeStr = args[i]
			}
		} else if arg == "-y" || arg == "--ctime" {
			i++
			if i < len(args) {
				cfg.CTimeStr = args[i]
			}
		} else if arg == "--files0-from" {
			i++
			if i < len(args) {
				cfg.Files0From = args[i]
			}
		} else if strings.HasPrefix(arg, "--files0-from=") {
			cfg.Files0From = strings.TrimPrefix(arg, "--files0-from=")
		} else if arg == "--files-from" {
			i++
			if i < len(args) {
				cfg.FilesFrom = args[i]
			}
		} else if strings.HasPrefix(arg, "--files-from=") {
			cfg.FilesFrom = strings.TrimPrefix(arg, "--files-from=")
		} else if arg == "--collapse" {
			i++
			if i < len(args) {
				cfg.Collapse = append(cfg.Collapse, args[i])
			}
		} else if strings.HasPrefix(arg, "--collapse=") {
			cfg.Collapse = append(cfg.Collapse, strings.TrimPrefix(arg, "--collapse="))
		} else if arg == "-m" || arg == "--filetime" {
			i++
			if i < len(args) {
				cfg.FileTimeFormat = args[i]
			}
		} else if strings.HasPrefix(arg, "--filetime=") {
			cfg.FileTimeFormat = strings.TrimPrefix(arg, "--filetime=")
		} else if arg == "-T" || arg == "--threads" {
			i++
			if i < len(args) {
				cfg.Threads, _ = strconv.Atoi(args[i])
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 && !strings.HasPrefix(arg, "--") {
			// Short flags group e.g. -csP or -n30
			parsed := false
			if strings.HasPrefix(arg, "-n") && len(arg) > 2 {
				val, err := strconv.Atoi(arg[2:])
				if err == nil {
					cfg.NumberOfLines = val
					cfg.hasExplicitN = true
					parsed = true
				}
			} else if strings.HasPrefix(arg, "-d") && len(arg) > 2 {
				val, err := strconv.Atoi(arg[2:])
				if err == nil {
					cfg.Depth = val
					parsed = true
				}
			} else if strings.HasPrefix(arg, "-w") && len(arg) > 2 {
				val, err := strconv.Atoi(arg[2:])
				if err == nil {
					cfg.TerminalWidth = val
					parsed = true
				}
			} else if strings.HasPrefix(arg, "-o") && len(arg) > 2 {
				cfg.OutputFormat = arg[2:]
				parsed = true
			} else if strings.HasPrefix(arg, "-m") && len(arg) > 2 {
				cfg.FileTimeFormat = arg[2:]
				parsed = true
			}

			if !parsed {
				for _, ch := range arg[1:] {
					switch ch {
					case 'p':
						cfg.FullPaths = true
					case 'L':
						cfg.DereferenceLinks = true
					case 'x':
						cfg.LimitFilesystem = true
					case 's':
						cfg.ApparentSize = true
					case 'r':
						cfg.Reverse = true
					case 'c':
						cfg.NoColors = true
					case 'C':
						cfg.ForceColors = true
					case 'b':
						cfg.NoPercentBars = true
					case 'B':
						cfg.BarsOnRight = true
					case 'R':
						cfg.ScreenReader = true
					case 'f':
						cfg.FileCount = true
					case 'i':
						cfg.IgnoreHidden = true
					case 't':
						cfg.FileTypes = true
					case 'P':
						cfg.NoProgress = true
					case 'D':
						cfg.OnlyDir = true
					case 'F':
						cfg.OnlyFile = true
					case 'j':
						cfg.OutputJSON = true
					default:
						fmt.Fprintf(os.Stderr, "error: unexpected argument '-%c' found\n\nUsage: executable [OPTIONS] [PATH]...\n\nFor more information, try '--help'.\n", ch)
						os.Exit(2)
					}
				}
			}
		} else if strings.HasPrefix(arg, "-") {
			fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]...\n\nFor more information, try '--help'.\n", arg, arg, arg)
			os.Exit(2)
		} else {
			cfg.Paths = append(cfg.Paths, arg)
		}
	}

	if !cfg.hasExplicitN && cfg.NumberOfLines <= 0 {
		_, termHeight := getTermSize()
		if termHeight > 10 {
			cfg.NumberOfLines = termHeight - 10
		} else {
			cfg.NumberOfLines = 20
		}
	}

	return cfg
}

func loadConfigFile(cfg *Config, filePath string) {
	lines := readLines(filePath)
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		val = strings.Trim(val, "\"'")

		switch key {
		case "reverse":
			cfg.Reverse = (val == "true")
		case "display-full-paths":
			cfg.FullPaths = (val == "true")
		case "display-apparent-size":
			cfg.ApparentSize = (val == "true")
		case "no-colors":
			cfg.NoColors = (val == "true")
		case "no-bars":
			cfg.NoPercentBars = (val == "true")
		case "bars-on-right":
			cfg.BarsOnRight = (val == "true")
		case "skip-total":
			cfg.SkipTotal = (val == "true")
		case "ignore-hidden":
			cfg.IgnoreHidden = (val == "true")
		case "output-format":
			cfg.OutputFormat = val
		case "number-of-lines":
			if n, err := strconv.Atoi(val); err == nil {
				cfg.NumberOfLines = n
				cfg.hasExplicitN = true
			}
		case "depth":
			if d, err := strconv.Atoi(val); err == nil {
				cfg.Depth = d
			}
		case "threads":
			if t, err := strconv.Atoi(val); err == nil {
				cfg.Threads = t
			}
		case "min-size":
			cfg.MinSizeStr = val
		case "screen-reader":
			cfg.ScreenReader = (val == "true")
		case "filecount":
			cfg.FileCount = (val == "true")
		case "file-types":
			cfg.FileTypes = (val == "true")
		case "only-dir":
			cfg.OnlyDir = (val == "true")
		case "only-file":
			cfg.OnlyFile = (val == "true")
		case "terminal-width":
			if w, err := strconv.Atoi(val); err == nil {
				cfg.TerminalWidth = w
			}
		}
	}
}

