			i++
			if i < len(args) {
				cfg.MTimeStr = args[i]
			}
		} else if arg == "-A" || arg == "--atime" {
			i++
			if i < len(args) {
				cfg.ATimeStr = args[i]
			}
		} else if arg == "-y" || arg == "--ctime" {
			i++
			if i < len(args) {
				cfg.CTimeStr = args[i]
			}
		} else if arg == "--files0-from" {
			i++
			if i < len(args) {
				cfg.Files0From = args[i]
			}
