			cfg.FilesFrom = strings.TrimPrefix(arg, "--files-from=")
		} else if arg == "--collapse" {
			i++
			if i < len(args) {
				cfg.Collapse = append(cfg.Collapse, args[i])
			}
		} else if strings.HasPrefix(arg, "--collapse=") {
			cfg.Collapse = append(cfg.Collapse, strings.TrimPrefix(arg, "--collapse="))
		} else if arg == "-m" || arg == "--filetime" {
			i++
			if i < len(args) {
				cfg.FileTimeFormat = args[i]
			}
		} else if strings.HasPrefix(arg, "--filetime=") {
			cfg.FileTimeFormat = strings.TrimPrefix(arg, "--filetime=")
		} else if arg == "-T" || arg == "--threads" {
			i++
			if i < len(args) {
				cfg.Threads, _ = strconv.Atoi(args[i])
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 && !strings.HasPrefix(arg, "--") {
			parsed := false
			if strings.HasPrefix(arg, "-n") && len(arg) > 2 {
				val, err := strconv.Atoi(arg[2:])
				if err == nil {
					cfg.NumberOfLines = val
					cfg.hasExplicitN = true
					parsed = true
				}
			} else if strings.HasPrefix(arg, "-d") && len(arg) > 2 {
				val, err := strconv.Atoi(arg[2:])
				if err == nil {
					cfg.Depth = val
					parsed = true
				}
			} else if strings.HasPrefix(arg, "-w") && len(arg) > 2 {
				val, err := strconv.Atoi(arg[2:])
				if err == nil {
					cfg.TerminalWidth = val
					parsed = true
				}
			} else if strings.HasPrefix(arg, "-o") && len(arg) > 2 {
				cfg.OutputFormat = arg[2:]
				parsed = true
			} else if strings.HasPrefix(arg, "-m") && len(arg) > 2 {
				cfg.FileTimeFormat = arg[2:]
				parsed = true
			}

			if !parsed {
				for _, ch := range arg[1:] {
					switch ch {
					case 'p':
						cfg.FullPaths = true
					case 'L':
						cfg.DereferenceLinks = true
					case 'x':
						cfg.LimitFilesystem = true
					case 's':
						cfg.ApparentSize = true
					case 'r':
						cfg.Reverse = true
					case 'c':
						cfg.NoColors = true
					case 'C':
						cfg.ForceColors = true
					case 'b':
						cfg.NoPercentBars = true
					case 'B':
						cfg.BarsOnRight = true
					case 'R':
						cfg.ScreenReader = true
					case 'f':
						cfg.FileCount = true
					case 'i':
						cfg.IgnoreHidden = true
					case 't':
						cfg.FileTypes = true
					case 'P':
						cfg.NoProgress = true
					case 'D':
						cfg.OnlyDir = true
					case 'F':
						cfg.OnlyFile = true
					case 'j':
						cfg.OutputJSON = true
					default:
						fmt.Fprintf(os.Stderr, "error: unexpected argument '-%c' found\n\nUsage: executable [OPTIONS] [PATH]...\n\nFor more information, try '--help'.\n", ch)
						os.Exit(2)
					}
				}
			}
		} else if strings.HasPrefix(arg, "-") {
			fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [PATH]...\n\nFor more information, try '--help'.\n", arg, arg, arg)
			os.Exit(2)
		} else {
			cfg.Paths = append(cfg.Paths, arg)
		}
	}

	if !cfg.hasExplicitN && cfg.NumberOfLines <= 0 {
		_, termHeight := getTermSize()
		if termHeight > 10 {
			cfg.NumberOfLines = termHeight - 10
		} else {
			cfg.NumberOfLines = 20
		}
	}

	return cfg
}

func loadConfigFile(cfg *Config, filePath string) {
	lines := readLines(filePath)
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		val = strings.Trim(val, "\"'")

		switch key {
		case "reverse":
			cfg.Reverse = (val == "true")
		case "display-full-paths":
			cfg.FullPaths = (val == "true")
		case "display-apparent-size":
			cfg.ApparentSize = (val == "true")
		case "no-colors":
			cfg.NoColors = (val == "true")
		case "no-bars":
			cfg.NoPercentBars = (val == "true")
		case "bars-on-right":
			cfg.BarsOnRight = (val == "true")
		case "skip-total":
			cfg.SkipTotal = (val == "true")
		case "ignore-hidden":
			cfg.IgnoreHidden = (val == "true")
		case "output-format":
			cfg.OutputFormat = val
		case "number-of-lines":
			if n, err := strconv.Atoi(val); err == nil {
				cfg.NumberOfLines = n
				cfg.hasExplicitN = true
			}
		case "depth":
			if d, err := strconv.Atoi(val); err == nil {
				cfg.Depth = d
			}
		case "threads":
			if t, err := strconv.Atoi(val); err == nil {
				cfg.Threads = t
			}
		case "min-size":
			cfg.MinSizeStr = val
		case "screen-reader":
			cfg.ScreenReader = (val == "true")
		case "filecount":
			cfg.FileCount = (val == "true")
		case "file-types":
			cfg.FileTypes = (val == "true")
		case "only-dir":
			cfg.OnlyDir = (val == "true")
		case "only-file":
			cfg.OnlyFile = (val == "true")
		case "terminal-width":
			if w, err := strconv.Atoi(val); err == nil {
				cfg.TerminalWidth = w
			}
		}
	}
}

func printShortHelp() {
	msg := "Like du but more intuitive\n\nUsage: executable [OPTIONS] [PATH]...\n\nArguments:\n  [PATH]...  Input files or directories\n\nOptions:\n  -d, --depth <DEPTH>              Depth to show\n  -T, --threads <THREADS>          Number of threads to use\n      --config <FILE>              Specify a config file to use\n  -n, --number-of-lines <NUMBER>   Number of lines of output to show. (Default is terminal_height - 10)\n  -p, --full-paths                 Subdirectories will not have their path shortened\n  -X, --ignore-directory <PATH>    Exclude any file or directory with this path\n  -I, --ignore-all-in-file <FILE>  Exclude any file or directory with a regex matching that listed in this file, the file entries will be added to the ignore regexs provided by --invert_filter\n  -L, --dereference-links          dereference sym links - Treat sym links as directories and go into them\n  -x, --limit-filesystem           Only count the files and directories on the same filesystem as the supplied directory\n  -s, --apparent-size              Use file length instead of blocks\n  -r, --reverse                    Print tree upside down (biggest highest)\n  -c, --no-colors                  No colors will be printed (Useful for commands like: watch)\n  -C, --force-colors               Force colors print\n  -b, --no-percent-bars            No percent bars or percentages will be displayed\n  -B, --bars-on-right              percent bars moved to right side of screen\n  -z, --min-size <MIN_SIZE>        Minimum size file to include in output\n  -R, --screen-reader              For screen readers. Removes bars. Adds new column: depth level (May want to use -p too for full path)\n      --skip-total                 No total row will be displayed\n  -f, --filecount                  Directory 'size' is number of child files instead of disk size\n  -i, --ignore-hidden              Do not display hidden files\n  -v, --invert-filter <REGEX>      Exclude filepaths matching this regex. To ignore png files type: -v \"\\.png$\"\n  -e, --filter <REGEX>             Only include filepaths matching this regex. For png files type: -e \"\\.png$\"\n  -t, --file-types                 show only these file types\n  -w, --terminal-width <WIDTH>     Specify width of output overriding the auto detection of terminal width\n  -P, --no-progress                Disable the progress indication\n      --print-errors               Print path with errors\n  -D, --only-dir                   Only directories will be displayed\n  -F, --only-file                  Only files will be displayed. (Finds your largest files)\n  -o, --output-format <FORMAT>     Changes output display size. si will print sizes in powers of 1000. b k m g t kb mb gb tb will print the whole tree in that size [possible values: si, b, k, m, g, t, kb, mb, gb, tb]\n  -S, --stack-size <STACK_SIZE>    Specify memory to use as stack size - use if you see: 'fatal runtime error: stack overflow' (default low memory=1048576, high memory=1073741824)\n  -j, --output-json                Output the directory tree as json to the current directory\n  -M, --mtime <MTIME>              +/-n matches files modified more/less than n days ago , and n matches files modified exactly n days ago, days are rounded down.That is +n => (−∞, curr−(n+1)), n => [curr−(n+1), curr−n), and -n => (𝑐𝑢𝑟𝑟−𝑛, +∞)\n  -A, --atime <ATIME>              just like -mtime, but based on file access time\n  -y, --ctime <CTIME>              just like -mtime, but based on file change time\n      --files0-from <FILES0_FROM>  Read NUL-terminated paths from FILE (use `-` for stdin)\n      --files-from <FILES_FROM>    Read newline-terminated paths from FILE (use `-` for stdin)\n      --collapse <COLLAPSE>        Keep these directories collapsed\n  -m, --filetime <FILETIME>        Directory 'size' is max filetime of child files instead of disk size. while a/c/m for last accessed/changed/modified time [possible values: a, c, m]\n  -h, --help                       Print help (see more with '--help')\n  -V, --version                    Print version\n"
